/// url = 'https://icr.healthcampaigns.org/StructureMap/DHIS2ValueToICR'
/// name = 'DHIS2ValueToICR'
/// title = 'DHIS2 value of one item, org unit and period to MeasureReport'
/// status = 'draft'

// Run by `fhir-pipes dhis2 reports --maps`, and by `fhir-pipes import run`
// over the records `dhis2 extract reports` writes.
//
// One summary MeasureReport per value, with a stratifier for each breakdown.
//
// References and systems are joined with `append` from source variables, not
// with FHIRPath: each FHIRPath call parses its expression and copies its input.

uses "https://healthcampaigns.org/fhir/dhis2/StructureDefinition/DHIS2Value" alias DHIS2Value as source
uses "http://hl7.org/fhir/StructureDefinition/MeasureReport" alias MeasureReport as target


// The systems, profiles and extensions it writes are parameters of the
// package (import.toml). Each is a constant here, so `append` and plain
// copies can use it; FHIRPath reads it as %name.
let base = %base;
let campaignExtension = %campaignExtension;
let periodExtension = %periodExtension;
let projectTagSystem = %projectTagSystem;
let sourceExtension = %sourceExtension;

group Value(source src : DHIS2Value, target r : MeasureReport) {
  src.id as id -> r.id = id "id";
  src.instance as i -> r.meta as meta, meta.tag as tag, tag.system = projectTagSystem, tag.code = i "tag";
  // The period extension is first: fhir-pipes reads the period from it.
  src.period as p -> r.extension as ext, ext.url = periodExtension, ext.value = p "period";
  src.campaign as c -> r.extension as ext, ext.url = campaignExtension, ext.value = create('Reference') as ref, ref.reference = c "campaign";
  src.source as s -> r.extension as ext, ext.url = sourceExtension, ext.value = create('CodeableConcept') as cc, cc.coding = translate(s, 'https://icr.healthcampaigns.org/ConceptMap/dhis2-value-source-to-report-source', 'Coding') "source";
  src -> r.status = 'complete' "status";
  src -> r.type = 'summary' "type";
  src.instance as i, src.indicatorKey as k -> r.measure = append(base, '/Measure/', i, '-', k) "measure";
  src -> r.subject as subject then {
    src.locationId as l -> subject.reference = append('Location/', l) "location";
    src.locationName as n -> subject.display = n "locationName";
  } "subject";
  src.date as d -> r.date = d "date";
  src.reporter as n -> r.reporter as reporter, reporter.display = n "reporter";
  src -> r.period as period then {
    src.periodStart as s -> period.start = s "periodStart";
    src.periodEnd as e -> period.end = e "periodEnd";
  } "reportPeriod";
  src -> r.group as g then {
    src -> g then Figures(src, g) "figures";
    src.stratifier as st -> g.stratifier as stratifier then Stratifier(src, st, stratifier) "stratifiers";
  } "group";
}

// The populations and score of the whole value, or of one stratum.
group Figures(source f, target g) {
  f.initialPopulation as n -> g.population as p, p.code as cc, cc.coding as c, c.system = 'http://terminology.hl7.org/CodeSystem/measure-population', c.code = 'initial-population', c.display = 'Initial Population', p.count = n "initialPopulation";
  f.numerator as n -> g.population as p, p.code as cc, cc.coding as c, c.system = 'http://terminology.hl7.org/CodeSystem/measure-population', c.code = 'numerator', c.display = 'Numerator', p.count = n "numerator";
  f.denominator as n -> g.population as p, p.code as cc, cc.coding as c, c.system = 'http://terminology.hl7.org/CodeSystem/measure-population', c.code = 'denominator', c.display = 'Denominator', p.count = n "denominator";
  f.score as s -> g.measureScore as q, q.value = s "score";
}

// One breakdown: the dimension as the stratifier's code, each option as a stratum.
group Stratifier(source src : DHIS2Value, source st, target stratifier) {
  st -> stratifier.code as cc then {
    st.dimension as d, st.name as n, src.instance as i -> cc.coding as c, c.system = append(base, '/CodeSystem/dhis2/', i, '/dimension'), c.code = d, c.display = n "dimensionCoding";
    st.name as n -> cc.text = n "dimensionText";
  } "dimension";
  st.stratum as s, st.dimension as d, src.instance as i -> stratifier.stratum as stratum then {
    s -> stratum.value as cc then {
      s.option as o, s.name as n -> cc.coding as c, c.system = append(base, '/CodeSystem/dhis2/', i, '/dimension/', d), c.code = o, c.display = n "optionCoding";
      s.name as n -> cc.text = n "optionText";
    } "option";
    s -> stratum then Figures(s, stratum) "stratumFigures";
  } "strata";
}
